const std=@import("std");const X=@import("experimental/hydration_exchange_signal.zig");const B=@import("experimental/hydration_exchange_quantum.zig");const M=X.M;const Q=@import("experimental/near_quantum.zig");const H=@import("experimental/hydration_signal.zig");const area:f64=7669529600;const conv=1e9/area;
const Fixture=struct{cell:M.Cell,liquid:f32,vapor:f32};
fn carbon(c:M.Cell)f64{var t:f64=c.detritus;for(c.cohorts)|co|t+=co.biomass;return t;}
fn nitrogen(c:M.Cell)f64{var t:f64=c.nutrient;for(c.cohorts)|co|t+=@as(f64,co.biomass)*M.nutrient_per_carbon;return t;}
fn funded(f:Fixture)Fixture{var x=f;var stores:[4]f64=undefined;var caps:[4]f64=undefined;for(x.cell.cohorts,0..)|c,i|{stores[i]=c.stored_water;caps[i]=M.waterCapacity(c);}if(Q.plan(x.liquid,conv,stores,caps))|p|if(Q.mergeEscrow(p,x.cell.liquid_return,stores,x.liquid,conv))|e|{x.liquid=p.pool;x.cell.liquid_return=e;for(&x.cell.cohorts,0..)|*c,i|c.stored_water=p.stores[i];};return x;}
fn run(f:Fixture,which:usize,law:u2,depth:f64,dt:f32,days:usize)!void{
 X.observed_uptake=0;X.observed_evaporation=0;var x=funded(f);const charge_total=X.total(x.cell,x.liquid,x.vapor,area);const initial_source=x.liquid;x.liquid=@floatCast(depth*1000/conv);const setup_delta=(@as(f64,x.liquid)-initial_source)*conv;const w0=X.total(x.cell,x.liquid,x.vapor,area);try std.testing.expectApproxEqAbs(charge_total+setup_delta,w0,1e-9);
 var co2:f64=1;var oxygen:f64=1;const c0=carbon(x.cell)+co2;const n0=nitrogen(x.cell);var fixed:f64=0;var recycled:f64=0;var grazed:f64=0;var maxw:f64=0;var maxc:f64=0;var maxn:f64=0;const ticks:usize=@intFromFloat(@as(f64,@floatFromInt(days))*86400/dt);var extinct:[4]?usize=.{null,null,null,null};
 const initial=x.cell;for(0..ticks)|tick|{const flux=X.step(law,&x.cell,&x.liquid,&x.vapor,area,.{.temperature=300,.depth_km=0,.light=1,.carbon_available=@floatCast(co2),.oxygen_carbon_capacity=@floatCast(oxygen)},dt).?;co2+=@as(f64,flux.recycled)-flux.fixed;oxygen+=@as(f64,flux.fixed)-flux.recycled;fixed+=flux.fixed;recycled+=flux.recycled;grazed+=flux.grazed;try std.testing.expect(co2>=0 and oxygen>=0);maxw=@max(maxw,@abs(X.total(x.cell,x.liquid,x.vapor,area)-w0));maxc=@max(maxc,@abs(carbon(x.cell)+co2-c0));maxn=@max(maxn,@abs(nitrogen(x.cell)-n0));try std.testing.expect(maxw<=1e-9 and maxc<=1e-4 and maxn<=1e-4);for(x.cell.cohorts,0..)|c,i|if(initial.cohorts[i].biomass>0 and c.biomass==0 and extinct[i]==null){extinct[i]=tick+1;};
 if((tick+1)%@as(usize,@intFromFloat(86400/dt))==0){const line=try std.json.stringifyAlloc(std.testing.allocator,.{.fixture=which,.law=law,.initial_depth_m=depth,.dt_s=dt,.horizon_days=days,.day=(tick+1)/@as(usize,@intFromFloat(86400/dt)),.setup_water_delta=setup_delta,.initial_cohorts=initial.cohorts,.cohorts=x.cell.cohorts,.extinction_tick=extinct,.liquid=x.liquid,.vapor=x.vapor,.liquid_return=x.cell.liquid_return,.vapor_return=x.cell.vapor_return,.fixed=fixed,.recycled=recycled,.grazed=grazed,.co2=co2,.oxygen=oxygen,.water_residual=maxw,.carbon_residual=maxc,.nitrogen_residual=maxn,.births_simulated=false,.uptake=X.observed_uptake,.evaporation=X.observed_evaporation,.last_height_m=X.observed_heights,.last_exposure=X.observed_exposures},.{});defer std.testing.allocator.free(line);std.debug.print("SIGNAL_MATRIX {s}\n",.{line});}
 }
}
test "frozen72 one-day and8 prolonged dry scenarios"{var arena=std.heap.ArenaAllocator.init(std.heap.page_allocator);defer arena.deinit();const parsed=try std.json.parseFromSlice([2]Fixture,arena.allocator(),@embedFile("experimental/exposure_fixtures.json"),.{});for(parsed.value,0..)|f,i|for(0..4)|law|for([_]f64{0,0.175,1})|depth|for([_]f32{1440,720,360})|dt|try run(f,i,@intCast(law),depth,dt,1);for(parsed.value,0..)|f,i|for(0..4)|law|try run(f,i,@intCast(law),0,1440,30);}
test "old signal path exact to frozen quantum exchange"{const parsed=try std.json.parseFromSlice([2]Fixture,std.testing.allocator,@embedFile("experimental/exposure_fixtures.json"),.{});defer parsed.deinit();for(parsed.value)|f|{var a=funded(f);var b=a;const e=M.Environment{.temperature=300,.depth_km=0,.light=1,.carbon_available=1,.oxygen_carbon_capacity=1};const af=X.step(0,&a.cell,&a.liquid,&a.vapor,area,e,1440).?;const bf=B.step(&b.cell,&b.liquid,&b.vapor,area,e,1440).?;try std.testing.expectEqualDeep(a,b);try std.testing.expectEqualDeep(af,bf);}}
